function validate([plants, capacity]) {
  if (!Array.isArray(plants) || plants.length < 1 || plants.length > 1000) return 'plants needs 1 to 1000 values.';
  if (plants.some(p => !Number.isInteger(p) || p < 1 || p > 1e6)) return 'Each plant needs between 1 and 10^6 units.';
  if (!Number.isInteger(capacity) || capacity > 1e9) return 'capacity is an integer of at most 10^9.';
  if (capacity < Math.max(...plants)) return 'capacity must be at least the largest plant need.';
  return null;
}

