function wateringPlants(plants, capacity) {
  // Walk one unit at a time and count every move.
  let position = -1;
  let water = capacity;
  let steps = 0;
  const walkTo = target => {
    while (position !== target) { position += position < target ? 1 : -1; steps++; }
  };
  for (let i = 0; i < plants.length; i++) {
    if (water < plants[i]) { walkTo(-1); water = capacity; }
    walkTo(i);
    water -= plants[i];
  }
  return steps;
}

