function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = int(900, 1000);
    const plants = Array.from({ length: n }, () => int(1, 1e6));
    const most = Math.max(...plants);
    const roll = rand();
    const capacity = roll < 0.15 ? 1e9 : roll < 0.3 ? most : most + int(0, 4e6);
    return [plants, capacity];
  }
  const n = int(1, 8);
  const top = rand() < 0.5 ? 4 : 9;
  const plants = Array.from({ length: n }, () => int(1, top));
  const most = Math.max(...plants);
  const capacity = rand() < 0.1 ? 1e9 : most + int(0, 2 * top);
  return [plants, capacity];
}
